WITH flattened AS (SELECT id, service, log_ts, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS attr_key, v) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, MIN(log_ts) AS first_log_ts, SUM(CASE WHEN attr_key = 'version' THEN latency_ms ELSE 0 END) AS version_latency_ms, BIT_AND(status_code) AS status_code_bit_and, CORR(latency_ms, status_code) AS corr_latency_ms_status_code, MIN(log_ts) AS first_log_ts_2, MAX(status_code) FILTER (WHERE attr_key = 'version') AS version_max_status_code, GROUPING_ID() AS gid FROM flattened GROUP BY CUBE (DATE_TRUNC('HOUR', log_ts)) ORDER BY status_code_bit_and DESC NULLS FIRST;
